// Formata o contrato da §4: { appointments: [{ appointment_id, service_name, start_at, status }] }
const linhas = $input.all().map(i => i.json);
const appointments = linhas.map(r => ({
  appointment_id: r.appointment_id,
  service_name: r.service_name,
  start_at: r.start_at,
  status: r.status
}));
return [{ json: { appointments } }];
